INSERT INTO notas (id, titulo, dominio_slug, aplicacao_slug, tipo_nota_slug, camadas, sinais, confianca, status, corpo) VALUES (
  $m3104$nota-0215$m3104$, $m3105$Eficiência mecânica no ciclismo É treinável ao longo de anos (~8% de melhora observada) — contradiz a crença antiga de que era praticamente fixa$m3105$, $m3106$fisiologia$m3106$,
  $m3107$contexto$m3107$, $m3108$conceito$m3108$,
  ARRAY[$m3109$mensal$m3109$]::text[], '{}'::text[],
  0.55, $m3110$ativo$m3110$, $m3111$Contraria a crença científica anterior de que a eficiência de pedalada/economia de corrida seriam praticamente fixas e pouco responsivas ao treino. Evidência mais recente mostra que a eficiência mecânica no ciclismo pode melhorar aproximadamente 8% ao longo de vários anos de treinamento consistente (mesmo em atletas de elite já treinados), enquanto a economia de corrida melhora entre 8-14% ao longo de anos. Os mecanismos exatos não são totalmente compreendidos, mas podem envolver mudanças na composição de isoformas das fibras musculares e outras adaptações de longo prazo do treino de endurance.

Aplicação ao feedback: reforça, com evidência adicional, que ganhos de eficiência/economia são um processo de anos (não semanas) — relevante para calibrar expectativas de progresso no feedback de longo prazo: se a FTP/potência não sobe rapidamente mas o atleta treina consistentemente há anos, parte do ganho de desempenho pode estar vindo de melhoria de eficiência (não capturada diretamente por FTP), consistente com a lógica de "economia se degrada com fadiga, mas melhora com treino consistente" já registrada na nota-0179/nota-0180.$m3111$
)
